def get_unattached_volumes(self):
        """Build a list of all volumes missing tags and not ignored. Returns a `dict` keyed by the issue_id with the
        volume as the value

        Returns:
            :obj:`dict` of `str`: `EBSVolume`
        """
        unattached_volumes = {}
        for volume in self.volumes.values():
            if not volume.tags or volume.tags.get("Name") in self.ignore_tags:
                continue
            if volume.is_attached:
                continue
            unattached_volumes[volume.id] = volume
        return unattached_volumes

